import test from "node:test";
import assert from "node:assert/strict";
import { evaluate, storageQuote, reset, historySize } from "../src/storage.ts";
import { storageEstimate, warehouseLabel } from "../src/warehouse.ts";

test("仓储报价与计量", async () => {
